def cross_product(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def orientation(p, q, r):
    val = cross_product(p, q, r)
    if val == 0:
        return 0  # collinear
    return 1 if val > 0 else 2  # clock or counterclock wise

def can_hit_all_with_two_shots(N, targets):
    if N <= 2:
        return "success"

    # Find the point with the lowest y-coordinate, break ties by x-coordinate
    start = min(targets, key=lambda p: (p[1], p[0]))

    # Sort points based on polar angle with start
    sorted_points = sorted(targets, key=lambda p: (orientation(start, p, (start[0] + 1, start[1])), p))

    # Check if all points can be covered by two lines
    # We need to check if there exists a line that can cover all points
    # or if there exists a line that can cover all but one point and another line that covers the remaining point

    # Check if all points are collinear
    if all(orientation(start, sorted_points[0], p) == 0 for p in sorted_points[1:]):
        return "success"

    # Check if we can find two lines
    for i in range(1, N):
        if orientation(start, sorted_points[i], sorted_points[(i + 1) % N]) != 0:
            # Try to find a line that covers all points except sorted_points[i]
            if all(orientation(sorted_points[i], sorted_points[(i + 1) % N], p) == 0 for p in sorted_points if p != sorted_points[i]):
